                        g = s * d(k+1);
                        d(k+1) = c * d(k+1) - s * o(k);
                        // o(k) is safe: k < u <= n-1, so k <= n-2, and o.size() == n-1
                        o(k) = c * o(k) + s * d(k+1);
                    }
                }

                // Update last element - only if u > 0 (so u-1 is valid index for o)
                if (u > 0) {
                    o(u-1) = f * s;
                }
                d(u) = f * c;
            }

            // Undo shift
            for (int i = l; i <= u; ++i) {
                d(i) += shift;
            }

            // Check convergence: if any off-diagonal is negligible, deflate
            bool deflated = false;
            // k ranges from l to u-1, and o(k) requires k < o.size()
            int k_end = std::min(u, (int)o.size());
            for (int k = l; k < k_end; ++k) {
                if (std::abs(o(k)) <= EPSI * (std::abs(d(k)) + std::abs(d(k+1)))) {
                    o(k) = ZERO;
                    // Split here
                    u = k;
                    deflated = true;
                    break;
                }
            }
            if (deflated) {
                break;
            }
        }

        // Move to next block
        if (u <= l) {
            l = l + 1;
            u = n - 1;
        } else {
            // Continue with [l, u-1] if deflated at bottom, else adjust
            if (u > l) {
                u = u - 1;
            }
        }
    }

    // Final sort ascending
    std::vector<double> temp;
    for (int i = 0; i < n; ++i) {
        temp.push_back(d(i));
    }
    std::sort(temp.begin(), temp.end());
    for (int i = 0; i < n; ++i) {
        d(i) = temp[i];
    }
}

